const COLORWAYS: Record<CarbnLogoColorway, { mark: string; word: string }> = {
  current: { mark: "currentColor", word: "currentColor" },
  graphite: { mark: "#08090b", word: "#08090b" },
  reversed: { mark: "#f4f5f7", word: "#f4f5f7" },
  "volt-on-dark": { mark: "#d0fe00", word: "#f4f5f7" },
  volt: { mark: "#d0fe00", word: "#d0fe00" },
};

export interface CarbnLogoProps
  extends Omit<SVGProps<SVGSVGElement>, "viewBox" | "role"> {
  form?: CarbnLogoForm;
  colorway?: CarbnLogoColorway;
  /** Accessible name. Defaults to "Carbn". */
  label?: string;
}

export function CarbnLogo({
  form = "lockup",
  colorway = "current",
  label = "Carbn",
  ...props
}: CarbnLogoProps) {
  const f = FORMS[form];
  const c = COLORWAYS[colorway];
  return (
    <svg viewBox={f.viewBox} role="img" aria-label={label} {...props}>
      <title>{label}</title>
      {f.mark.length > 0 && (
        <g fill={c.mark}>
          {f.mark.map((p, i) => (
            <path key={i} d={p.d} transform={p.transform} />
          ))}
        </g>
      )}
      {f.word.length > 0 && (
        <g fill={c.word}>
          {f.word.map((p, i) => (
            <path key={i} d={p.d} transform={p.transform} />
          ))}
        </g>
      )}
    </svg>
  );
}
